{
  "name": "USB-TMC实验光源",
  "name_en": "USB-TMC Light Source",
  "manufacturer": "",
  "description": "通过 USB-TMC 通信控制的实验室光源，可进行开关、光强设定、运行时长设定、状态查询、温度读取和预设配方激活，适用于实验中的照明、激发或定时曝光场景。",
  "description_en": "A laboratory light source controlled over USB-TMC communication, supporting on/off control, intensity setting, runtime setting, status queries, temperature readout, and preset recipe activation for lab illumination, excitation, or timed exposure tasks.",
  "tag_hints": [
    "light source control",
    "USB-TMC",
    "intensity control",
    "timed illumination",
    "temperature monitoring",
    "recipe/profile selection"
  ],
  "actions": [
    {
      "action_name": "auto-on",
      "description": "打开光源。",
      "description_en": "Turn the light source on."
    },
    {
      "action_name": "auto-off",
      "description": "关闭光源。",
      "description_en": "Turn the light source off."
    },
    {
      "action_name": "auto-set_state",
      "description": "设置光源开关状态。",
      "description_en": "Set the light source on/off state."
    },
    {
      "action_name": "auto-query_on_state",
      "description": "查询光源当前是否开启。",
      "description_en": "Query whether the light source is currently on."
    },
    {
      "action_name": "auto-get_status",
      "description": "读取设备状态信息。",
      "description_en": "Get device status information."
    },
    {
      "action_name": "auto-get_run_status",
      "description": "读取设备运行状态。",
      "description_en": "Get the current run status."
    },
    {
      "action_name": "auto-set_runtime",
      "description": "设置光源运行时长。",
      "description_en": "Set the light source runtime duration."
    },
    {
      "action_name": "auto-get_runtime",
      "description": "读取光源运行时长设置。",
      "description_en": "Get the configured runtime duration."
    },
    {
      "action_name": "auto-set_intensity",
      "description": "设置光强百分比。",
      "description_en": "Set the output intensity percentage."
    },
    {
      "action_name": "auto-get_intensity",
      "description": "读取光强百分比。",
      "description_en": "Get the output intensity percentage."
    },
    {
      "action_name": "auto-get_temperatures",
      "description": "读取设备温度信息。",
      "description_en": "Get device temperature readings."
    },
    {
      "action_name": "auto-activate_recipe",
      "description": "激活预设配方或工作模式。",
      "description_en": "Activate a preset recipe or operating profile."
    }
  ]
}

